export const conversationVocabulary: VocabWord[] = SPOKEN_ROWS.map(
  ([word, phonetic, meaning, definition, sourceRank], index) => ({
    id: `spoken-${index + 1}`,
    word,
    phonetic: phonetic ? `/${phonetic.replace(/^\/|\/$/g, '')}/` : '',
    meaning,
    definition,
    example: '',
    translation: '',
    day: 1,
    sourceRank,
  })
);
